-- MindEase minimal complete development dataset.
-- Intended for an empty counselling_system schema.
-- Passwords are Werkzeug scrypt hashes generated by generate_password_hash().

START TRANSACTION;


SET @teacher_one_user = (SELECT id FROM users WHERE USN = 'TEACH001');
SET @teacher_two_user = (SELECT id FROM users WHERE USN = 'TEACH002');
SET @teacher_three_user = (SELECT id FROM users WHERE USN = 'TEACH003');
SET @student_one_user = (SELECT id FROM users WHERE USN = 'STUD001');
SET @student_two_user = (SELECT id FROM users WHERE USN = 'STUD002');
SET @student_three_user = (SELECT id FROM users WHERE USN = 'STUD003');


SET @teacher_one = (SELECT id FROM teachers WHERE user_id = @teacher_one_user);
SET @teacher_two = (SELECT id FROM teachers WHERE user_id = @teacher_two_user);
SET @teacher_three = (SELECT id FROM teachers WHERE user_id = @teacher_three_user);


SET @student_one = (SELECT id FROM students WHERE user_id = @student_one_user);
SET @student_two = (SELECT id FROM students WHERE user_id = @student_two_user);
SET @student_three = (SELECT id FROM students WHERE user_id = @student_three_user);

-- Gives each student a different teacher-initiated-request state to test.

SET @teacher_request_one = (SELECT id FROM teacher_counselling_requests WHERE teacher_id = @teacher_one AND student_id = @student_one);
SET @teacher_request_two = (SELECT id FROM teacher_counselling_requests WHERE teacher_id = @teacher_two AND student_id = @student_two);

-- One responded/open request, one completed/confidential request, and one pending request.
SET @request_one = LAST_INSERT_ID();

SET @request_two = LAST_INSERT_ID();

SET @request_three = LAST_INSERT_ID();




COMMIT;
